mapper.select:
select * from conversations
where id = #{id} and tenant_id = #{tenantId} and user_id = #{userId}
limit 1

select *
from conversations
where tenant_id = #{tenantId}
  and user_id = #{userId}
  and knowledge_base_id = #{knowledgeBaseId}
order by updated_at desc, created_at desc
limit 1

select *
from conversations
where tenant_id = #{tenantId}
  and user_id = #{userId}
  and knowledge_base_id = #{knowledgeBaseId}
order by updated_at desc, created_at desc
limit #{limit}

select *
from conversations
where tenant_id = #{tenantId}
  and user_id = #{userId}
  and knowledge_base_id = #{knowledgeBaseId}
  and (
    #{keyword} = ''
    or lower(title) like concat('%', lower(#{keyword}), '%')
    or cast(id as char) like concat('%', #{keyword}, '%')
  )
order by updated_at desc, created_at desc
limit #{limit} offset #{offset}

select count(1)
from conversations
where tenant_id = #{tenantId}
  and user_id = #{userId}
  and knowledge_base_id = #{knowledgeBaseId}
  and (
    #{keyword} = ''
    or lower(title) like concat('%', lower(#{keyword}), '%')
    or cast(id as char) like concat('%', #{keyword}, '%')
  )
